import { tags } from "typia";

/**
 * Period descriptor for aggregated dashboard metrics.
 *
 * This type indicates the date range and preset used to compute the statistics
 * returned by the refunds and disputes dashboard. It is primarily a UI
 * convenience structure so that admins can clearly see which window the metrics
 * cover.
 *
 * Implementations may use either explicit date bounds, a named preset, or both,
 * depending on the dashboard configuration and query capabilities.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallDashboardPeriod = {
  /**
   * Named preset representing the aggregation window.
   *
   * Common values include `today`, `last_7_days`, `last_30_days`,
   * `this_month`, or other business-specific presets configured by the
   * platform.
   */
  preset: string;

  /**
   * Inclusive calendar date on which the aggregation period starts.
   *
   * When present, it is typically normalized to midnight in the reporting
   * timezone. It may be null if the dashboard relies solely on a preset
   * without explicit dates.
   */
  start_date?: (string & tags.Format<"date">) | null | undefined;

  /**
   * Inclusive calendar date on which the aggregation period ends.
   *
   * When set, it usually corresponds to the most recent date included in the
   * aggregated statistics. It may be null for open-ended or preset-only
   * periods.
   */
  end_date?: (string & tags.Format<"date">) | null | undefined;
};
